/**
 * RPC 오류 운영 보고의 앱 경계.
 *
 * 정확한 오류율을 계산하지 않는다. 서버가 정상 업무 거절을 다시 걸러 내고, 예상 밖 오류만
 * 5분 버킷으로 합친다. 오류 문구와 사용자 입력은 전송하지 않는다.
 */
export type RpcFailureShape = {
  code?: string | null;
  details?: string | null;
};

export type RpcFailureReport = {
  p_code: string;
  p_detail: string;
  p_client_platform: string;
};

export type RpcFailureReporter = (payload: RpcFailureReport) => PromiseLike<unknown>;

/** 보고 실패가 원래 화면 오류를 덮지 않도록 fire-and-forget으로 끝낸다. */
export function reportRpcFailure(
  reporter: RpcFailureReporter,
  error: RpcFailureShape,
  platform: string,
): void {
  try {
    void Promise.resolve(reporter({
      p_code: error.code ?? 'NO_CODE',
      p_detail: error.details ?? 'NONE',
      p_client_platform: platform,
    })).catch(() => undefined);
  } catch {
    // 보고기가 동기적으로 실패해도 원래 RPC 오류 흐름은 그대로 돌려준다.
  }
}

/**
 * Supabase 클라이언트. 세션은 네이티브에서 expo-secure-store, 웹에서 localStorage 에 저장.
 * 환경변수: EXPO_PUBLIC_SUPABASE_URL · EXPO_PUBLIC_SUPABASE_ANON_KEY (.env)
 *
 * ⚠ 화면은 여기를 직접 부르지 않는다. 도메인별 features 하위 hooks.ts 가 유일한 경계다.
 *   예전에는 이 파일에 RPC 래퍼(rpc.e1ConfirmInbound 등)를 따로 뒀는데,
 *   훅이 생기면서 같은 호출을 두 군데서 하게 되어 무효화 규칙이 갈라졌다. 래퍼는 걷어냈다.
 */
import { createClient } from '@supabase/supabase-js';
import type { Database } from '@margincook/db';
import { Platform } from 'react-native';
import * as SecureStore from 'expo-secure-store';
import { reportRpcFailure } from './rpcMonitoring';

/**
 * 세션 저장소는 플랫폼마다 다르다.
 *
 * ⚠ 웹에서 expo-secure-store 는 **빈 껍데기**다(ExpoSecureStore.web.js 가 `export default {}`).
 *   구분 없이 쓰면 앱이 뜨자마자 세션을 읽다가 죽는다:
 *     "ExpoSecureStore.default.getValueWithKeyAsync is not a function"
 *   CLAUDE.md 가 `--web` 을 미리보기 수단으로 두고 있으므로 웹도 동작해야 한다.
 *
 * 웹은 localStorage 를 쓴다. 브라우저 미리보기는 개발용이라 기기 보안 저장소가 필요 없고,
 * SSR/비브라우저 환경에서 localStorage 가 없을 수 있어 접근 전에 확인한다.
 */
const SecureStoreAdapter = {
  getItem: (key: string) => SecureStore.getItemAsync(key),
  setItem: (key: string, value: string) => SecureStore.setItemAsync(key, value),
  removeItem: (key: string) => SecureStore.deleteItemAsync(key),
};

const hasLocalStorage = (): boolean =>
  typeof globalThis !== 'undefined' && typeof globalThis.localStorage !== 'undefined';

const WebStorageAdapter = {
  getItem: async (key: string) => (hasLocalStorage() ? globalThis.localStorage.getItem(key) : null),
  setItem: async (key: string, value: string) => {
    if (hasLocalStorage()) globalThis.localStorage.setItem(key, value);
  },
  removeItem: async (key: string) => {
    if (hasLocalStorage()) globalThis.localStorage.removeItem(key);
  },
};

const sessionStorage = Platform.OS === 'web' ? WebStorageAdapter : SecureStoreAdapter;

const ENV_URL = process.env.EXPO_PUBLIC_SUPABASE_URL ?? '';
const SUPABASE_ANON_KEY = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY ?? '';

/**
 * ⚠ **웹 미리보기는 LAN IP 를 탈 이유가 없다.**
 *
 * .env 의 주소는 **폰(Expo Go)** 이 PC 에 닿기 위한 것이다. 그런데 브라우저는
 * Supabase 와 같은 기계에서 도니 localhost 로 충분하다. LAN IP 를 쓰면
 * PC 의 IP 가 바뀔 때마다(오늘만 세 번) 웹이 조용히 옛 주소로 요청해
 * "정보를 불러오지 못했어요"가 된다 — 서버는 멀쩡한데.
 *
 * 그래서 웹은 항상 로컬 주소를 쓰고, .env 의 IP 는 네이티브에만 쓴다.
 * 포트는 .env 에서 가져와 로컬 Supabase 포트를 바꿔도 따라간다.
 */
const localPort = (() => {
  const m = /:(\d+)\s*$/.exec(ENV_URL.trim());
  return m ? m[1] : '54321';
})();

const SUPABASE_URL = Platform.OS === 'web' ? `http://127.0.0.1:${localPort}` : ENV_URL;

/**
 * 환경변수 설정 여부. 화면은 "로딩"과 "환경 미설정"을 구분해서 보여야 한다.
 * 미설정 상태로 조회하면 네트워크 오류처럼 보여 원인을 오해하게 된다.
 */
export const isSupabaseConfigured = SUPABASE_URL !== '' && SUPABASE_ANON_KEY !== '';

// 생성 타입을 물려 RPC 인자·반환과 테이블 컬럼이 **컴파일 단계에서** 검증되게 한다.
// 스키마를 바꾸면 `pnpm db:types` 로 타입을 다시 만들어야 여기 오류가 드러난다.
export const supabase = createClient<Database>(
  SUPABASE_URL || 'http://localhost:54321',
  SUPABASE_ANON_KEY,
  {
    auth: {
      storage: sessionStorage,
      autoRefreshToken: true,
      persistSession: true,
      detectSessionInUrl: false,
    },
  },
);

/**
 * 입고 확정 1회분의 멱등성 키.
 * 버튼을 누른 시점에 한 번 만들어 state 에 보관하고, 재시도에는 같은 값을 다시 넘긴다.
 * 보안 토큰이 아니라 중복 제거용 식별자라 난수 품질 요구가 낮다(crypto 의존을 피한다).
 */
export const makeInboundKey = (orderId: string): string =>
  `${orderId}:${Date.now().toString(36)}:${Math.random().toString(36).slice(2, 10)}`;

/**
 * 서버가 거절한 이유를 **코드로** 들고 다니는 오류.
 *
 * ⚠ 예전엔 `new Error(error.message)` 로 문구만 남겼고, 화면은 그 한국어를 검사해
 *   분기했다(`isClosedError` 등). 그래서 0140 에서 문구 하나를 고칠 때 판별식도
 *   같이 고쳐야 했고, 한쪽만 고치면 **화면이 오류를 못 알아봤다.**
 *
 * ⚠ 코드베이스 주석에는 "PostgREST 응답에 SQLSTATE 가 그대로 오지 않는 경우가 있다"
 *   고 적혀 있었는데 **실측해 보니 틀렸다.** 그대로 온다:
 *       {"code":"45010","details":"SALE_DATE_OUT_OF_RANGE","hint":null,"message":"…"}
 *   `code` 가 SQLSTATE, `details` 가 서버가 붙인 안정된 이름이다(0144).
 */
export class RpcError extends Error {
  /** SQLSTATE. 45001 BEFORE_OPEN · 45002 DAY_CLOSED · 45009 REVISION_CONFLICT · 45010 SALE_DATE_OUT_OF_RANGE · 45011 DAY_IS_LIVE */
  readonly code: string | null;
  /** 서버가 `detail` 로 붙인 이름. 로그에서 읽기 좋다. */
  readonly detail: string | null;

  constructor(message: string, code: string | null, detail: string | null) {
    super(message);
    this.name = 'RpcError';
    this.code = code;
    this.detail = detail;
  }
}

/** supabase-js 의 오류를 `RpcError` 로 옮긴다. 문구는 그대로 두고 코드를 살린다. */
export function rpcError(e: { message: string; code?: string | null; details?: string | null }): RpcError {
  if (isSupabaseConfigured) {
    reportRpcFailure(
      (payload) => supabase.rpc('report_client_rpc_error', payload),
      e,
      Platform.OS,
    );
  }
  return new RpcError(e.message, e.code ?? null, e.details ?? null);
}

import { describe, expect, it, vi } from 'vitest';
import { reportRpcFailure } from '@/lib/rpcMonitoring';

describe('reportRpcFailure', () => {
  it('코드·안정 detail·플랫폼만 보내고 오류 문구는 보내지 않는다', async () => {
    const reporter = vi.fn(async () => ({ data: { reported: true }, error: null }));

    reportRpcFailure(reporter, {
      code: 'XX001',
      details: 'INTERNAL_FAILURE',
      message: '사용자 입력이나 DB 문구가 섞일 수 있는 값',
    } as { code: string; details: string; message: string }, 'android');

    await vi.waitFor(() => expect(reporter).toHaveBeenCalledTimes(1));
    expect(reporter).toHaveBeenCalledWith({
      p_code: 'XX001',
      p_detail: 'INTERNAL_FAILURE',
      p_client_platform: 'android',
    });
    expect(JSON.stringify(reporter.mock.calls)).not.toContain('사용자 입력');
  });

  it('코드·detail이 없는 네트워크 오류는 안정된 대체값으로 보낸다', async () => {
    const reporter = vi.fn(async () => ({ data: null, error: null }));
    reportRpcFailure(reporter, {}, 'web');
    await vi.waitFor(() => expect(reporter).toHaveBeenCalledWith({
      p_code: 'NO_CODE',
      p_detail: 'NONE',
      p_client_platform: 'web',
    }));
  });

  it('운영 보고 실패가 처리되지 않은 Promise 오류가 되지 않는다', async () => {
    const reporter = vi.fn(async () => { throw new Error('monitor unavailable'); });
    reportRpcFailure(reporter, { code: '08006', details: null }, 'ios');
    await vi.waitFor(() => expect(reporter).toHaveBeenCalledTimes(1));
  });

  it('보고기가 동기적으로 실패해도 원래 오류 처리를 가로막지 않는다', () => {
    const reporter = vi.fn(() => { throw new Error('sync monitor failure'); });
    expect(() => reportRpcFailure(reporter, { code: '08006' }, 'web')).not.toThrow();
    expect(reporter).toHaveBeenCalledTimes(1);
  });
});

/**
 * P1-1 원격 ACL audit의 실제 DB·모바일 RPC 허용 목록 회귀시험.
 *
 * 배포 audit 자체는 현재 미승인 authenticated RPC를 실패시킨다. 이 시험은 그 위험을
 * 성공으로 바꾸지 않고, 새 DB에서 SQL이 끝까지 실행되어 정확한 metric을 한 번씩 내며
 * 이미 닫힌 사후조건 값을 유지하는지를 잰다. 프로브 rollback과 모바일 .rpc 호출 이름↔허용 목록의
 * 양방향 일치도 확인하며, 대조할 수 없는 동적 .rpc 이름은 허용하지 않는다.
 */
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { scanMobileRpcNames } from './admin-acl-source-scan.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..', '..');
const SQL_PATH = join(HERE, 'admin-acl-audit.sql');
const MOBILE_ROOTS = [
  join(ROOT, 'apps', 'mobile', 'src'),
  join(ROOT, 'apps', 'mobile', 'app'),
];
const CONTAINER = process.env.SUPABASE_DB_CONTAINER ?? 'supabase_db_margincook';
const DATABASE = process.argv[2] ?? process.env.PGDATABASE;

if (!/^[A-Za-z0-9_.-]{1,128}$/.test(CONTAINER)) {
  console.error('SUPABASE_DB_CONTAINER 형식이 아닙니다');
  process.exit(2);
}
if (!DATABASE || !/^[a-z_][a-z0-9_]{0,62}$/.test(DATABASE)) {
  console.error('사용법: node packages/db/scripts/admin-acl-audit.test.mjs <DB 식별자>');
  process.exit(2);
}

const EXPECTED_METRICS = new Map([
  ['migrations', 'expected=2'],
  ['probe_owner', 'expected=postgres'],
  ['probe_dangerous', 'expected=0'],
  ['public_dangerous', 'expected=0'],
  ['rls_disabled_app_tables', 'expected=0'],
  ['protected_objects', 'expected=6'],
  ['protected_writes', 'expected=0'],
  ['ledger_write_paths', 'expected=0'],
  ['source_schema_grants', 'expected=0'],
  ['supabase_admin_objects', 'expected=0'],
  ['anon_rpc', 'expected=0'],
  ['blocked_internal_rpc', 'expected=0'],
  ['blocked_internal_rpc_objects', 'expected=11'],
  ['rpc_executor_role', 'expected=1'],
  ['rpc_executor_facades_invalid', 'expected=0'],
  ['rpc_executor_privileged_maintenance', 'expected=0'],
  ['rls_policy_helper_calls', 'expected=0'],
  ['facade_rpc_objects', 'expected=65'],
  ['facade_rpc_missing', 'expected=0'],
  ['unapproved_authenticated_rpc', 'expected=0'],
  ['platform_default_open', 'informational'],
]);

function fail(message) {
  console.error(`admin-acl audit 회귀시험 실패: ${message}`);
  process.exit(1);
}

function psql(input) {
  const result = spawnSync(
    'docker',
    ['exec', '-i', CONTAINER, 'psql', '-U', 'postgres', '-d', DATABASE, '-v', 'ON_ERROR_STOP=1', '-q', '-t', '-A'],
    { input, encoding: 'utf8' },
  );
  if (result.status !== 0) fail(`${result.stderr || result.stdout || 'psql 실행 실패'}`.trim());
  return String(result.stdout ?? '');
}

function auditSqlWithAllowlistExports(sql) {
  const finalRollback = /rollback;\s*$/i.exec(sql);
  if (!finalRollback) fail('감사 SQL의 마지막 rollback을 찾지 못했습니다');
  const beforeRollback = sql.slice(0, finalRollback.index);
  return `${beforeRollback}
select '__acl_approved_rpc|' || signature from _acl_approved_rpc order by signature;
select '__acl_non_mobile_rpc|' || signature || '|' || consumer
  from _acl_non_mobile_rpc order by signature;
rollback;
`;
}

function difference(left, right) {
  return [...left].filter((value) => !right.has(value)).sort();
}

const sql = readFileSync(SQL_PATH, 'utf8');
const raw = psql(`set search_path to pg_catalog;\n${auditSqlWithAllowlistExports(sql)}`);
const outputLines = raw.split(/\r?\n/).filter(Boolean);
const approvedSignatures = outputLines
  .filter((line) => line.startsWith('__acl_approved_rpc|'))
  .map((line) => line.slice('__acl_approved_rpc|'.length));
const nonMobileRows = outputLines
  .filter((line) => line.startsWith('__acl_non_mobile_rpc|'))
  .map((line) => line.split('|'));
const nonMobileSignatures = nonMobileRows.map(([, signature]) => signature);
const rows = outputLines
  .filter((line) => !line.startsWith('__acl_approved_rpc|') && !line.startsWith('__acl_non_mobile_rpc|'))
  .map((line) => line.split('|'));
const seen = new Map();

for (const [metric, value, expected, ...extra] of rows) {
  if (!metric || value === undefined || expected === undefined || extra.length) fail(`잘못된 metric 행: ${[metric, value, expected, ...extra].join('|')}`);
  if (seen.has(metric)) fail(`중복 metric: ${metric}`);
  seen.set(metric, { value, expected });
}
for (const [metric, expected] of EXPECTED_METRICS) {
  if (!seen.has(metric)) fail(`누락 metric: ${metric}`);
  if (seen.get(metric).expected !== expected) fail(`${metric} 기대 설명 불일치: ${seen.get(metric).expected}`);
}
for (const metric of seen.keys()) if (!EXPECTED_METRICS.has(metric)) fail(`알 수 없는 metric: ${metric}`);
if (seen.get('probe_owner').value !== 'postgres') fail(`프로브 소유자: ${seen.get('probe_owner').value}`);
if (seen.get('facade_rpc_missing').value !== '0') fail(`허용 facade가 DB에 없습니다: ${seen.get('facade_rpc_missing').value}`);

// 새 DB가 이미 만족하는 사후조건은 값까지 고정해 후속 migration의 GRANT·RLS 회귀를 즉시 잡는다.
const FRESH_DB_VALUES = new Map([
  ['probe_dangerous', '0'],
  ['public_dangerous', '0'],
  ['rls_disabled_app_tables', '0'],
  ['protected_objects', '6'],
  ['protected_writes', '0'],
  ['source_schema_grants', '0'],
  ['supabase_admin_objects', '0'],
  ['anon_rpc', '0'],
  ['blocked_internal_rpc', '0'],
  ['blocked_internal_rpc_objects', '11'],
  ['rpc_executor_role', '1'],
  ['rpc_executor_facades_invalid', '0'],
  ['rpc_executor_privileged_maintenance', '0'],
  ['rls_policy_helper_calls', '0'],
  ['facade_rpc_objects', '65'],
]);
for (const [metric, expectedValue] of FRESH_DB_VALUES) {
  const observed = seen.get(metric).value;
  if (observed !== expectedValue) fail(`${metric} 사후조건 불일치: 관측=${observed} 기대=${expectedValue}`);
}

// CLI 장부가 없으면 0만, 있으면 0166·0167 둘 모두를 의미하는 2만 허용한다.
const migrationLedger = psql("select case when to_regclass('supabase_migrations.schema_migrations') is null then 'absent' else 'present' end;").trim();
const expectedMigrations = migrationLedger === 'present' ? '2' : '0';
if (seen.get('migrations').value !== expectedMigrations) {
  fail(`migrations 값이 하네스 계약 밖입니다: 관측=${seen.get('migrations').value} 장부=${migrationLedger} 기대=${expectedMigrations}`);
}

const probe = psql("select coalesce(to_regclass('public._acl_probe_postgres')::text, 'absent');").trim();
if (probe !== 'absent') fail(`rollback 뒤 프로브가 남았습니다: ${probe}`);

if (approvedSignatures.length === 0) fail('허용 RPC 시그니처를 하나도 추출하지 못했습니다');
if (new Set(approvedSignatures).size !== approvedSignatures.length) fail('허용 RPC 시그니처가 중복됐습니다');
if (nonMobileRows.some((row) => row.length !== 3 || !row[1] || !row[2])) fail('비-mobile RPC 출력 형식이 잘못됐습니다');
const approvedNames = new Set(approvedSignatures.map((signature) => signature.slice(0, signature.indexOf('('))));
if (approvedNames.has('comment_only_rpc')) fail('SQL 주석을 허용 RPC로 잘못 읽었습니다');
const nonMobileNames = new Set(nonMobileSignatures.map((signature) => signature.slice(0, signature.indexOf('('))));
const strayNonMobile = difference(nonMobileNames, approvedNames);
if (strayNonMobile.length) fail(`비-mobile 예외가 허용 목록에 없습니다: ${strayNonMobile.join(', ')}`);
const expectedMobileNames = new Set([...approvedNames].filter((name) => !nonMobileNames.has(name)));
let sourceNames;
try {
  sourceNames = scanMobileRpcNames(MOBILE_ROOTS);
} catch (error) {
  fail(error instanceof Error ? error.message : String(error));
}
const missingFromAllowlist = difference(sourceNames, expectedMobileNames);
const unusedAllowlist = difference(expectedMobileNames, sourceNames);
if (missingFromAllowlist.length || unusedAllowlist.length) {
  fail(`모바일 RPC↔허용 목록 불일치 — 미허용=[${missingFromAllowlist.join(', ')}] 미사용=[${unusedAllowlist.join(', ')}]`);
}

// P0-5 이후에는 부채 상한이 아니라 0이 계약이다. 하나라도 다시 열리면 즉시 실패한다.
for (const metric of ['ledger_write_paths', 'unapproved_authenticated_rpc']) {
  const observed = seen.get(metric).value;
  if (observed !== '0') fail(`${metric} 최소 권한 회귀: 관측=${observed} 기대=0`);
}

console.log(`admin-acl audit 실제 DB 계약 통과 — metric ${seen.size}개 · 모바일 RPC ${sourceNames.size}개 · 비-mobile 예외 ${nonMobileNames.size}개`);
console.log(`  관측값: rls_disabled_app_tables=${seen.get('rls_disabled_app_tables').value} ledger_write_paths=${seen.get('ledger_write_paths').value} unapproved_authenticated_rpc=${seen.get('unapproved_authenticated_rpc').value}`);

const json = (body, status) => new Response(JSON.stringify(body), {
  status,
  headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
});

/** 길이까지 포함해 토큰 비교 시간이 값의 앞부분 일치 여부에 좌우되지 않게 한다. */
export function safeEqual(left, right) {
  const a = new TextEncoder().encode(String(left ?? ''));
  const b = new TextEncoder().encode(String(right ?? ''));
  const length = Math.max(a.length, b.length);
  let diff = a.length ^ b.length;
  for (let i = 0; i < length; i += 1) diff |= (a[i] ?? 0) ^ (b[i] ?? 0);
  return diff === 0;
}

export function serviceKeyOf(env) {
  const keyMap = env.get('SUPABASE_SECRET_KEYS');
  if (keyMap) {
    try {
      const parsed = JSON.parse(keyMap);
      if (typeof parsed?.default === 'string' && parsed.default) return parsed.default;
    } catch {
      return null;
    }
  }
  return env.get('SUPABASE_SERVICE_ROLE_KEY') || null;
}

export async function handleOpsHealth(req, env, fetchImpl = fetch) {
  if (req.method !== 'GET') return json({ status: 'method_not_allowed' }, 405);

  const expectedToken = env.get('OPS_HEALTH_TOKEN');
  const suppliedToken = req.headers.get('x-ops-health-token');
  if (!expectedToken || !safeEqual(suppliedToken, expectedToken)) {
    return json({ status: 'unauthorized' }, 401);
  }

  const url = env.get('SUPABASE_URL');
  const key = serviceKeyOf(env);
  if (!url || !key) return json({ status: 'unavailable' }, 503);

  try {
    const headers = { apikey: key, 'content-type': 'application/json' };
    // legacy service_role JWT는 PostgREST Authorization에도 싣는다. 새 sb_secret 키는 apikey만 쓴다.
    if (key.startsWith('eyJ')) headers.authorization = `Bearer ${key}`;
    const response = await fetchImpl(`${url}/rest/v1/rpc/ops_health_status`, {
      method: 'POST',
      headers,
      body: '{}',
    });
    if (!response.ok) return json({ status: 'unavailable' }, 503);
    const body = await response.json();
    if (!body || !['ok', 'degraded'].includes(body.status)) {
      return json({ status: 'unavailable' }, 503);
    }
    return json(body, body.status === 'ok' ? 200 : 503);
  } catch {
    return json({ status: 'unavailable' }, 503);
  }
}

if (typeof Deno !== 'undefined') {
  Deno.serve((req) => handleOpsHealth(req, Deno.env));
}

-- 0176 · Cron/RPC 운영 관측의 최소 안전망
--
-- 정확한 RPC 오류율은 플랫폼 요청 로그가 있어야 계산할 수 있다. 이 단계는 그 수치를
-- 지어내지 않고, 앱이 보고한 예상 밖 RPC 오류 건수와 pg_cron 실행 지연·실패만 다룬다.
-- 원본 오류 문구와 사용자 입력은 저장하지 않는다.

begin;

create schema if not exists ops;
revoke all on schema ops from public, anon, authenticated, margincook_rpc_executor;
grant usage on schema ops to service_role;

create table ops.rpc_error_buckets (
  bucket_at timestamptz not null,
  user_id uuid not null,
  error_code text not null,
  error_detail text not null,
  client_platform text not null,
  occurrence_count integer not null default 1 check (occurrence_count between 1 and 20),
  first_seen_at timestamptz not null,
  last_seen_at timestamptz not null,
  primary key (bucket_at, user_id, error_code, error_detail, client_platform),
  constraint rpc_error_code_shape check (error_code ~ '^[A-Z0-9]{3,10}$'),
  constraint rpc_error_detail_shape check (error_detail ~ '^[A-Z0-9_]{1,80}$'),
  constraint rpc_error_platform_shape check (client_platform in ('android', 'ios', 'web', 'unknown'))
);

create table ops.monitoring_config (
  singleton boolean primary key default true check (singleton),
  started_at timestamptz not null
);
insert into ops.monitoring_config(singleton, started_at)
values (true, clock_timestamp());

alter table ops.rpc_error_buckets enable row level security;
alter table ops.monitoring_config enable row level security;
revoke all on table ops.rpc_error_buckets, ops.monitoring_config
  from public, anon, authenticated, margincook_rpc_executor;
grant select, insert, update, delete on table ops.rpc_error_buckets, ops.monitoring_config to service_role;

comment on table ops.rpc_error_buckets is
  '앱이 보고한 예상 밖 RPC 오류를 사용자·5분·오류 지문별로 합친 운영 신호. 정확한 전체 오류율이 아니다.';

create or replace function ops.is_expected_rpc_error(p_code text, p_detail text)
returns boolean
language sql
immutable
set search_path = pg_catalog
as $$
  select
    coalesce(upper(btrim(p_code)), '') ~ '^450(0[1-9]|1[0-5])$'
    or coalesce(upper(btrim(p_code)), '') = '22000'
    or coalesce(upper(btrim(p_detail)), '') = any (array[
      'ARCHIVE_REASON_REQUIRED', 'BASE_REQUIRED', 'BASIS_NOT_AVAILABLE',
      'BEFORE_OPEN', 'DAY_CLOSED', 'DAY_IS_LIVE', 'EMPTY_PAYLOAD',
      'HOURS_NOT_HERE', 'INVALID_ARCHIVE_REASON', 'INVALID_TRANSITION',
      'INVALID_VALUE', 'LATE_OPEN', 'NO_CHANGES', 'NONEXISTENT_LOCAL_TIME',
      'PURGE_APPROVAL_REQUIRED', 'PURGE_BACKUP_REQUIRED', 'PURGE_NOT_SCHEDULED',
      'RETENTION_PERIOD_ACTIVE', 'REVISION_CONFLICT', 'SALE_DATE_OUT_OF_RANGE',
      'STORE_LIFECYCLE_APPEND_ONLY', 'STORE_NOT_ARCHIVED',
      'STORE_OWNERSHIP_RESTORE_FORBIDDEN', 'STORE_OWNERSHIP_TRANSFER_FORBIDDEN',
      'STORE_PURGE_PROCEDURE_REQUIRED', 'UNKNOWN_KEY'
    ]::text[])
$$;

revoke execute on function ops.is_expected_rpc_error(text, text)
  from public, anon, authenticated, margincook_rpc_executor;
grant execute on function ops.is_expected_rpc_error(text, text) to service_role;

create or replace function public.report_client_rpc_error(
  p_code text,
  p_detail text,
  p_client_platform text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, ops
as $$
declare
  v_user uuid := auth.uid();
  v_now timestamptz := clock_timestamp();
  v_bucket timestamptz;
  v_code text := upper(coalesce(nullif(btrim(p_code), ''), 'NO_CODE'));
  v_detail text := upper(coalesce(nullif(btrim(p_detail), ''), 'NONE'));
  v_platform text := lower(coalesce(nullif(btrim(p_client_platform), ''), 'unknown'));
  v_recent integer;
  v_count integer;
begin
  if v_user is null then
    raise exception '로그인이 필요해요' using errcode = '42501', detail = 'AUTH_REQUIRED';
  end if;

  -- 정상 업무 분기·입력 거절은 장애가 아니다. 서버가 다시 판정하므로 호출자가 숨길 수 없다.
  if ops.is_expected_rpc_error(v_code, v_detail) then
    return jsonb_build_object('reported', false, 'reason', 'expected');
  end if;

  if v_code !~ '^[A-Z0-9]{3,10}$' then
    v_code := 'BAD_CODE';
  end if;
  if v_detail !~ '^[A-Z0-9_]{1,80}$' then
    v_detail := 'UNSTRUCTURED';
  end if;
  if v_platform not in ('android', 'ios', 'web') then
    v_platform := 'unknown';
  end if;

  -- 같은 사용자의 동시 보고도 합계 검사를 함께 통과하지 못하게 직렬화한다.
  perform pg_advisory_xact_lock(hashtext('ops_rpc_error'), hashtext(v_user::text));

  -- 한 계정은 15분 동안 최대 20건만 반영한다. 같은 오류의 반복도 20에서 멈춘다.
  select coalesce(sum(occurrence_count), 0)::integer into v_recent
    from ops.rpc_error_buckets
   where user_id = v_user and bucket_at >= v_now - interval '15 minutes';
  if v_recent >= 20 then
    return jsonb_build_object('reported', false, 'reason', 'rate_limited');
  end if;

  v_bucket := date_trunc('hour', v_now)
    + make_interval(mins => (extract(minute from v_now)::integer / 5) * 5);

  insert into ops.rpc_error_buckets
    (bucket_at, user_id, error_code, error_detail, client_platform,
     occurrence_count, first_seen_at, last_seen_at)
  values
    (v_bucket, v_user, v_code, v_detail, v_platform, 1, v_now, v_now)
  on conflict (bucket_at, user_id, error_code, error_detail, client_platform)
  do update set
    occurrence_count = least(ops.rpc_error_buckets.occurrence_count + 1, 20),
    last_seen_at = excluded.last_seen_at
  returning occurrence_count into v_count;

  return jsonb_build_object('reported', true, 'count', v_count);
end;
$$;

revoke execute on function public.report_client_rpc_error(text, text, text)
  from public, anon, margincook_rpc_executor;
grant execute on function public.report_client_rpc_error(text, text, text)
  to authenticated, service_role;

comment on function public.report_client_rpc_error(text, text, text) is
  '인증 앱이 만난 예상 밖 RPC 오류의 코드·안정 detail·플랫폼만 5분 버킷으로 보고한다. 오류율 분모는 제공하지 않는다.';

create or replace function public.ops_health_status()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, ops
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_cron_monitored boolean;
  v_cron_ok boolean := false;
  v_jobs jsonb := '[]'::jsonb;
  v_rpc_count integer := 0;
  v_rpc_users integer := 0;
  v_rpc_fingerprints jsonb := '[]'::jsonb;
  v_started_at timestamptz;
begin
  select started_at into v_started_at from ops.monitoring_config where singleton;
  v_cron_monitored := to_regclass('cron.job') is not null
    and current_setting('cron.database_name', true) = current_database();

  if v_cron_monitored then
    with expected(jobname, schedule, max_age) as (values
      ('margincook-close-due', '* * * * *', interval '5 minutes'),
      ('margincook-apply-breaks', '* * * * *', interval '5 minutes'),
      ('margincook-purge-changes', '17 4 * * *', interval '30 hours')
    ), observed as (
      select e.jobname, e.schedule as expected_schedule, e.max_age,
             j.job_count, j.actual_schedule, j.active,
             r.last_success_at, r.last_failure_at, r.last_status
        from expected e
        left join lateral (
          select count(*)::integer job_count,
                 max(c.schedule) actual_schedule,
                 bool_and(c.active) active,
                 array_agg(c.jobid) job_ids
            from cron.job c where c.jobname = e.jobname
        ) j on true
        left join lateral (
          select max(coalesce(d.end_time, d.start_time)) filter (where d.status = 'succeeded') last_success_at,
                 max(coalesce(d.end_time, d.start_time)) filter
                   (where d.status not in ('succeeded', 'running')) last_failure_at,
                 (array_agg(d.status order by d.start_time desc, d.runid desc))[1] last_status
            from cron.job_run_details d where d.jobid = any(j.job_ids)
        ) r on true
    ), shaped as (
      select *,
             job_count = 1 and active is true and actual_schedule = expected_schedule
             and (v_now - coalesce(last_success_at, v_started_at) <= max_age)
             and (last_failure_at is null or last_success_at >= last_failure_at) as healthy
        from observed
    )
    select coalesce(bool_and(healthy), false),
           coalesce(jsonb_agg(jsonb_build_object(
             'name', jobname,
             'healthy', healthy,
             'active', coalesce(active, false),
             'schedule', actual_schedule,
             'last_status', last_status,
             'last_success_at', last_success_at,
             'last_failure_at', last_failure_at
           ) order by jobname), '[]'::jsonb)
      into v_cron_ok, v_jobs
      from shaped;
  end if;

  select coalesce(sum(occurrence_count), 0)::integer,
         count(distinct user_id)::integer
    into v_rpc_count, v_rpc_users
    from ops.rpc_error_buckets
   where bucket_at >= v_now - interval '15 minutes';

  select coalesce(jsonb_agg(jsonb_build_object(
           'code', error_code, 'detail', error_detail,
           'platform', client_platform, 'count', n
         ) order by n desc, error_code, error_detail), '[]'::jsonb)
    into v_rpc_fingerprints
    from (
      select error_code, error_detail, client_platform, sum(occurrence_count)::integer n
        from ops.rpc_error_buckets
       where bucket_at >= v_now - interval '15 minutes'
       group by error_code, error_detail, client_platform
       order by n desc, error_code, error_detail
       limit 5
    ) x;

  return jsonb_build_object(
    'status', case when v_cron_ok and v_rpc_count = 0 then 'ok' else 'degraded' end,
    'checked_at', v_now,
    'cron', jsonb_build_object('monitored', v_cron_monitored, 'healthy', v_cron_ok, 'jobs', v_jobs),
    'rpc', jsonb_build_object(
      'source', 'client_reported',
      'window_minutes', 15,
      'unexpected_count', v_rpc_count,
      'affected_users', v_rpc_users,
      'fingerprints', v_rpc_fingerprints
    )
  );
end;
$$;

revoke execute on function public.ops_health_status()
  from public, anon, authenticated, margincook_rpc_executor;
grant execute on function public.ops_health_status() to service_role;

comment on function public.ops_health_status() is
  'service_role 전용 운영 상태. Cron 3종의 최신 성공·실패·지연과 최근 15분 client-reported RPC 오류 건수를 반환한다.';

-- 기존 하루 한 번 청소 문에서 운영 신호도 30일 뒤 제거한다. 계산 원장과 감사 원장은 건드리지 않는다.
create or replace function public.purge_entity_changes()
returns integer
language plpgsql
security definer
set search_path = public, ops, pg_temp
as $$
declare
  v_n integer := 0;
  v_part integer;
begin
  delete from public.entity_change_events
   where occurred_at < clock_timestamp() - interval '30 days';
  get diagnostics v_part = row_count;
  v_n := v_n + v_part;

  delete from ops.rpc_error_buckets
   where bucket_at < clock_timestamp() - interval '30 days';
  get diagnostics v_part = row_count;
  v_n := v_n + v_part;
  return v_n;
end;
$$;

revoke execute on function public.purge_entity_changes()
  from public, anon, authenticated, margincook_rpc_executor;
grant execute on function public.purge_entity_changes() to service_role;

do $verify$
begin
  if has_schema_privilege('authenticated', 'ops', 'usage')
     or has_table_privilege('authenticated', 'ops.rpc_error_buckets', 'select')
     or has_table_privilege('authenticated', 'ops.rpc_error_buckets', 'insert')
     or has_table_privilege('authenticated', 'ops.monitoring_config', 'select') then
    raise exception '0176: 앱 롤에 ops 원본이 열려 있습니다';
  end if;
  if not has_function_privilege('authenticated',
       'public.report_client_rpc_error(text,text,text)', 'execute')
     or has_function_privilege('authenticated', 'public.ops_health_status()', 'execute') then
    raise exception '0176: 보고 문과 운영 상태 문의 권한이 맞지 않습니다';
  end if;
  if has_function_privilege('margincook_rpc_executor',
       'public.ops_health_status()', 'execute')
     or has_function_privilege('margincook_rpc_executor',
       'public.purge_entity_changes()', 'execute') then
    raise exception '0176: 앱 내부 실행 역할에 전역 운영 문이 열려 있습니다';
  end if;
end;
$verify$;

commit;

-- ════════════════════════════════════════════════════════════════
-- 16 · 수정 내역 보관 30일 (0076)
--
-- 사장님: "사용자는 최근 7일 확인 → 서버는 30일 보관 → 핵심 장부는 영구 보존"
--
-- 이 정책이 안전한 이유는 하나다:
--   **수정 내역을 통째로 지워도 재고·단가·손익이 하나도 안 움직인다.**
-- 그게 사실인지 여기서 확인한다. 사실이 아니라면 지우면 안 되는 데이터다.
-- ════════════════════════════════════════════════════════════════

-- 청소는 전 매장 유지보수 문이라 service_role/소유자만 부른다. 시험 본문이
-- executor 권한을 넓히지 않도록 소유자 호출을 헬퍼 하나로 고정한다.
create function pg_temp.purge_changes_for_test() returns integer
language plpgsql as $h$
declare v_n integer;
begin
  set local role postgres;
  v_n := purge_entity_changes();
  set local role margincook_rpc_executor;
  return v_n;
end $h$;

do $t$
declare
  v_ing  uuid := pg_temp.ing('대파');
  v_rcp  uuid := pg_temp.rcp('제육볶음');
  v_day  date := pg_temp.today();
  -- 지우기 전 계산값
  v_price0 numeric;  v_stock0 numeric;  v_mat0 numeric;  v_profit0 numeric;
  v_ledger0 int;     v_orders0 int;     v_ptrend0 int;   v_ftrend0 int;
  v_snap0  jsonb;
  v_n      int;
begin
  -- ⚠ 닫혀 있으면 **다시 열어야** 한다. 앱에서 영업을 한 번 마치면 그날은 closed 로 남고,
  --   여는 데 실패한다. 그 상태로 두면 이 파일이 통째로 빨개진다(실제로 그랬다).
  perform pg_temp.open_today();   -- 열린 영업일을 보장한다(프렐류드 헬퍼)

  -- 내역이 쌓이도록 몇 가지를 실제로 바꾼다.
  perform quick_inbound(pg_temp.store(), v_ing, 1000, 6000, 2, null, v_day, 'T16-A');
  perform save_recipe(pg_temp.store(), jsonb_build_object(
    'id', v_rcp, 'name', '제육볶음', 'price', 12500, 'base_servings', 10));
  perform pg_temp.ok('내역이 쌓였다',
    (select count(*) from entity_change_events where store_id = pg_temp.store()) > 0);

  -- ── 지우기 전 값을 모두 잡는다 ──────────────────────────────
  v_price0  := base_unit_price(v_ing);
  v_stock0  := stock_total_base(v_ing);
  select material_cost, profit into v_mat0, v_profit0
    from recipe_list(pg_temp.store()) where id = v_rcp;
  select count(*) into v_ledger0 from inventory_events where store_id = pg_temp.store();
  select count(*) into v_orders0 from order_records where store_id = pg_temp.store();
  select count(*) into v_ptrend0 from price_trends where store_id = pg_temp.store();
  select count(*) into v_ftrend0 from profit_trends where store_id = pg_temp.store();
  v_snap0 := (select snapshot from business_days
               where store_id = pg_temp.store() and business_date = v_day);

  -- ── 수정 내역을 **전부** 나이 들게 한 뒤 청소한다 ───────────
  -- ⚠ 직접 delete 하면 RLS 에 막혀 0건이 지워지고 조용히 성공한다.
  --   실제 청소 경로(purge_entity_changes)를 그대로 쓴다.
  -- ⚠ 이 원장은 SELECT·INSERT 만 열려 있다 — 사용자가 자기 이력을 고치거나
  --   골라 지울 수 없어야 하기 때문이다. 그래서 **나이를 들리는 것도 막힌다.**
  --   시험용으로만 잠깐 권한을 되돌린다(트랜잭션 안이라 롤백된다).
  execute 'reset role';
  update entity_change_events
     set occurred_at = clock_timestamp() - interval '40 days'
   where store_id = pg_temp.store();
  execute 'set local role margincook_rpc_executor';
  v_n := pg_temp.purge_changes_for_test();
  perform pg_temp.ok('청소가 실제로 지운다', v_n > 0);
  perform pg_temp.eq('내역이 비었다',
    (select count(*) from entity_change_events where store_id = pg_temp.store()), 0, 0);

  -- ── 계산 근거는 하나도 안 움직여야 한다 ─────────────────────
  perform pg_temp.eq('기준단가 그대로',  base_unit_price(v_ing), v_price0, 0.000001);
  perform pg_temp.eq('재고 그대로',      stock_total_base(v_ing), v_stock0, 0.000001);
  perform pg_temp.eq('레시피 재료비 그대로',
    (select material_cost from recipe_list(pg_temp.store()) where id = v_rcp), v_mat0, 0.000001);
  perform pg_temp.eq('레시피 순이익 그대로',
    (select profit from recipe_list(pg_temp.store()) where id = v_rcp), v_profit0, 0.000001);

  perform pg_temp.eq('재고 원장 그대로',
    (select count(*) from inventory_events where store_id = pg_temp.store()), v_ledger0, 0);
  perform pg_temp.eq('구매·입고 이력 그대로',
    (select count(*) from order_records where store_id = pg_temp.store()), v_orders0, 0);
  perform pg_temp.eq('가격 추이 그대로',
    (select count(*) from price_trends where store_id = pg_temp.store()), v_ptrend0, 0);
  perform pg_temp.eq('손익 추이 그대로',
    (select count(*) from profit_trends where store_id = pg_temp.store()), v_ftrend0, 0);
  perform pg_temp.ok('그날 영업 기준(스냅샷)도 그대로',
    (select snapshot from business_days
      where store_id = pg_temp.store() and business_date = v_day) = v_snap0);

  -- 마스터의 갱신 시각도 남는다 — "마지막으로 언제 고쳤나"는 여기로도 안다.
  perform pg_temp.ok('레시피 updated_at 은 남는다',
    (select updated_at from recipes where id = v_rcp) is not null);
end $t$;

-- ════════════════════════════════════════════════════════════════
-- 30일이 지난 것만 지운다
-- ════════════════════════════════════════════════════════════════

do $t$
declare
  v_ing uuid := pg_temp.ing('양파');
  v_day date := pg_temp.today();
  v_old uuid;
  v_new int;
  v_n   int;
begin
  -- ⚠ 닫혀 있으면 **다시 열어야** 한다. 앱에서 영업을 한 번 마치면 그날은 closed 로 남고,
  --   여는 데 실패한다. 그 상태로 두면 이 파일이 통째로 빨개진다(실제로 그랬다).
  perform pg_temp.open_today();   -- 열린 영업일을 보장한다(프렐류드 헬퍼)

  perform quick_inbound(pg_temp.store(), v_ing, 1000, 2000, 1, null, v_day, 'T16-B');
  select count(*) into v_new from entity_change_events where store_id = pg_temp.store();
  perform pg_temp.ok('새 내역이 있다', v_new > 0);

  -- 한 건만 40일 전으로 밀어 놓는다.
  select id into v_old from entity_change_events
   where store_id = pg_temp.store() order by occurred_at desc limit 1;
  -- ⚠ 이 원장은 SELECT·INSERT 만 열려 있다 — 사용자가 자기 이력을 고치거나
  --   골라 지울 수 없어야 하기 때문이다. 그래서 **나이를 들리는 것도 막힌다.**
  --   시험용으로만 잠깐 권한을 되돌린다(트랜잭션 안이라 롤백된다).
  execute 'reset role';
  update entity_change_events
     set occurred_at = clock_timestamp() - interval '40 days'
   where id = v_old;
  execute 'set local role margincook_rpc_executor';
  v_n := pg_temp.purge_changes_for_test();
  perform pg_temp.eq('40일 지난 것만 지워진다', v_n, 1, 0);
  perform pg_temp.eq('나머지는 남는다',
    (select count(*) from entity_change_events where store_id = pg_temp.store()), v_new - 1, 0);

  -- 29일 된 것은 살아 있어야 한다 — 경계에서 하루 일찍 지우면 안 된다.
  execute 'reset role';
  update entity_change_events
     set occurred_at = clock_timestamp() - interval '29 days'
   where id = (select id from entity_change_events
                where store_id = pg_temp.store() order by occurred_at desc limit 1);
  execute 'set local role margincook_rpc_executor';
  perform pg_temp.eq('29일 된 것은 안 지운다', pg_temp.purge_changes_for_test(), 0, 0);

  -- ⚠ 청소가 실패해도 영업 시작이 막히면 안 된다 — 곁일이다.
  perform pg_temp.ok('영업 시작에 청소가 붙어 있다',
    pg_get_functiondef('public.open_business_day(uuid,date,time)'::regprocedure)
      like '%purge_entity_changes%');
end $t$;


-- ── 누가 부를 수 있는가 (0135) ────────────────────────────────
/*
 * ⚠ 실측으로 확인된 취약점이다. 일회용 새 DB 에서 —
 *     45일 전으로 늙힌 수정내역 128건
 *     set role anon;  select purge_entity_changes(1);   →  128
 *     남은 수정내역 0건
 *   로그인도 안 한 사람이 **모든 매장의** 수정 내역을 지웠다.
 *
 * 원인이 둘이었다 —
 *   ① 이 함수는 definer 인데 매장을 안 가린다(0076 이 일부러 그렇게 뒀다).
 *      대신 **누가 부를 수 있는지**가 좁아야 하는데 안 좁았다.
 *   ② 새 함수의 실행 권한 기본값이 `PUBLIC` 이고 Supabase 기본 권한이 anon 에도 준다.
 *
 * 그리고 `p_days` 를 받으니 `1` 을 넣어 보관 기간을 무시할 수 있었다.
 * 보관 기간은 **정책**이지 호출자가 정할 값이 아니다.
 */
do $t$
declare v_old uuid; v_n int;
begin
  -- ① anon 은 못 부른다. 권한 값이 아니라 **실제로 내려가서** 본다.
  perform pg_temp.raises('anon 은 청소를 못 부른다',
    'set local role anon; select purge_entity_changes()', '42501');

  -- ② 인자가 아예 없다 — 보관 기간을 호출자가 못 줄인다.
  perform pg_temp.eq('인자 있는 옛 함수가 없다',
    (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = 'purge_entity_changes'
        and pg_get_function_identity_arguments(p.oid) <> ''), 0, 0);
  perform pg_temp.raises('1일을 넣어도 안 먹는다',
    'select purge_entity_changes(1)', '42883');   -- undefined_function

  /*
   * ③ 30일 이내 기록은 유지된다. (위 ② 로 기간을 못 줄이니 이건 그 결과다.)
   * ⚠ 행을 새로 만들지 않고 **있는 것을 늙힌다.** 컬럼 목록을 손으로 적으면
   *   스키마가 바뀔 때 이 시험만 조용히 깨진다 — 실제로 한 번 그랬다.
   */
  execute 'reset role';
  select id into v_old from entity_change_events
   where store_id = pg_temp.store() order by occurred_at desc limit 1;
  update entity_change_events
     set occurred_at = clock_timestamp() - interval '20 days'
   where id = v_old;
  execute 'set local role margincook_rpc_executor';

  v_n := pg_temp.purge_changes_for_test();
  perform pg_temp.ok('20일 된 기록은 살아 있다',
    exists (select 1 from entity_change_events where id = v_old));

  -- ④ 정상 경로(영업 시작)의 30일 정리는 계속 돈다.
  execute 'reset role';
  update entity_change_events set occurred_at = clock_timestamp() - interval '40 days'
   where id = v_old;
  execute 'set local role margincook_rpc_executor';

  /*
   * ⚠ 닫았다 다시 여는 것으로는 확인이 안 된다. 그 경로는 `reopen_business_day` 라
   *   청소가 안 붙어 있다 — 처음에 그렇게 짰다가 시험이 빨갛게 돼서 알았다.
   *   청소는 **새 영업일을 만들 때** 도는 곁일이므로, 오늘 장부를 과거 날짜로 옮겨
   *   진짜 `open_business_day` 가 돌게 만든다(트랜잭션 안이라 롤백된다).
   */
  execute 'reset role';
  update business_days set business_date = date '2020-01-02', status = 'closed'
   where store_id = pg_temp.store() and business_date = pg_temp.today();
  execute 'set local role margincook_rpc_executor';

  perform pg_temp.open_today();          -- 여기서 청소가 곁일로 돈다
  perform pg_temp.ok('영업 시작이 40일 된 기록을 정리한다',
    not exists (select 1 from entity_change_events where id = v_old));
end $t$;


-- ── 함수 권한의 기본값 (0135 · 0136) ──────────────────────────
/*
 * ⚠ 이건 한 함수의 문제가 아니라 **기본값**의 문제다. 그리고 그 기본값은 **두 층**이다 —
 *   한쪽만 걷으면 절반만 걷힌다. 0135 가 실제로 그랬다.
 *
 *       PUBLIC 은 PostgreSQL 의 **전역** 기본값   → `in schema` 를 **빼야** 걷힌다
 *       anon   은 Supabase 의 **스키마별** 기본값 → `in schema` 를 **줘야** 걷힌다
 *
 *   실측: `in schema` 만 쓰면 새로 만든 함수가 `PUBLIC=true anon=true` 로 그대로 생긴다.
 *   (0135 에는 "template 기본값이 이긴다"고 적었는데 **틀린 설명이었다.** template 과
 *    무관하다. 0136 이 바로잡았다.)
 *
 *   빨개지면 두 층 중 하나가 빠진 것이다. 0136 의 세 문장을 그대로 쓰면 된다:
 *       alter default privileges for role postgres
 *         revoke execute on functions from public;                    -- 전역
 *       alter default privileges for role postgres in schema public
 *         revoke execute on functions from anon;                      -- 스키마별
 *       alter default privileges for role postgres in schema public
 *         grant  execute on functions to authenticated, service_role;
 */
do $t$
declare v_n int; v_names text;
begin
  select count(*), string_agg(p.proname, ', ' order by p.proname)
    into v_n, v_names
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.prokind = 'f'
     and has_function_privilege('anon', p.oid, 'execute');
  perform pg_temp.eq(
    coalesce('anon 이 부를 수 있는 함수: ' || v_names, 'anon 이 부를 수 있는 함수 없음'),
    v_n, 0, 0);

  -- 0174부터 반대 계약이다. 앱은 공식 facade만 호출하며 내부 계산·몸통은 실행 역할에만 연다.
  perform pg_temp.ok('정상 facade는 인증 사용자가 부를 수 있다',
    has_function_privilege('authenticated',
      'public.transition_business_state(uuid, text, time)', 'execute'));
  perform pg_temp.ok('내부 계산은 인증 사용자에게 닫혀 있다',
    not has_function_privilege('authenticated',
      'public.base_unit_price(uuid)', 'execute'));
  perform pg_temp.ok('RLS 도우미도 Data API 문이 아니다',
    not has_function_privilege('authenticated', 'public.my_store_ids()', 'execute'));

  -- 그리고 그 예외는 **정말로** 막혀 있어야 한다. 목록에만 적고 열려 있으면 의미가 없다.
  perform pg_temp.ok('크론 전용 함수는 인증 사용자도 못 부른다',
    not has_function_privilege('authenticated', 'public.close_due_business_days()', 'execute'));
  perform pg_temp.ok('크론 전용 함수는 anon 도 못 부른다',
    not has_function_privilege('anon', 'public.close_due_business_days()', 'execute'));
  /*
   * ⚠ 마감 **몸통**은 권한 검사를 안 한다. 열어 두면 사장님이 직접 불러
   *   `close_method`·`closed_at` 을 아무 값으로나 적을 수 있다(0138).
   *   사람이 들어오는 문은 `close_business_day` 하나뿐이어야 한다.
   */
  perform pg_temp.ok('마감 몸통은 인증 사용자도 못 부른다',
    not has_function_privilege('authenticated',
      'public.close_business_day_row(uuid,business_close_method)', 'execute'));
  -- 0160 부터 사람의 문은 전이 RPC 다 — close_business_day 도 내부 몸통이 됐다.
  perform pg_temp.ok('그래도 정상 문은 열려 있다',
    has_function_privilege('authenticated', 'public.transition_business_state(uuid, text, time)', 'execute')
    and not has_function_privilege('authenticated', 'public.close_business_day(uuid)', 'execute'));

  /*
   * ⚠ 앞의 두 줄은 **지금 있는** 함수만 본다. 정작 위험한 건 다음에 만들어질 함수다 —
   *   0135 의 확인이 딱 그래서 통과했고, 실제로는 절반만 걷혀 있었다.
   *   그러니 **진짜로 하나 만들어** 본다(트랜잭션 안이라 롤백된다).
   *
   *   빨개지면 기본 권한 두 층 중 하나가 빠진 것이다(0136):
   *     PUBLIC 은 전역   → `alter default privileges for role postgres revoke … from public`
   *     anon   은 스키마별 → `… for role postgres in schema public revoke … from anon`
   */
  execute 'reset role';
  execute 'create function public.zz_grant_probe() returns int language sql as ''select 1''';
  -- ⚠ 빨개지면 기본 권한 **두 층** 중 하나가 빠진 것이다(위 머리말 참고).
  perform pg_temp.ok('새로 만든 함수는 PUBLIC 이 못 부른다',
    not has_function_privilege('public', 'public.zz_grant_probe()', 'execute'));
  perform pg_temp.ok('새로 만든 함수는 anon 도 못 부른다',
    not has_function_privilege('anon', 'public.zz_grant_probe()', 'execute'));
  perform pg_temp.ok('새 함수는 인증 사용자에게 자동 공개되지 않는다',
    not has_function_privilege('authenticated', 'public.zz_grant_probe()', 'execute'));
  perform pg_temp.ok('새 함수는 전용 실행 역할에도 자동 공개되지 않는다',
    not has_function_privilege('margincook_rpc_executor', 'public.zz_grant_probe()', 'execute'));
  perform pg_temp.ok('새 함수는 service_role에는 열린다',
    has_function_privilege('service_role', 'public.zz_grant_probe()', 'execute'));
  execute 'drop function public.zz_grant_probe()';
  execute 'set local role margincook_rpc_executor';
end $t$;


-- ── SECURITY DEFINER 허용 목록 (0136) ─────────────────────────
/*
 * definer 함수는 **RLS 를 지나간다.** 그래서 하나 늘 때마다 그게 매장을 가리는지
 * 사람이 봐야 한다 — `purge_entity_changes` 가 안 가려서 이번 일이 났다.
 *
 * 여기 목록을 못 박아 두면, 새 definer 함수가 생길 때 시험이 빨개진다.
 * 그때 할 일은 목록에 이름을 더하는 게 아니라 **그 함수가 매장을 가리는지 보는 것**이다.
 *
 * 지금 다섯의 근거:
 *   my_store_ids                 auth.uid() 로 자기 매장만. 이게 RLS 의 뿌리다.
 *   purge_entity_changes         매장을 안 가린다. 대신 30일 고정 + anon 차단(0135).
 *   set_operating_hours          첫 줄이 assert_my_store 다(0132).
 *   save_settings · save_store_tax  settings 를 쓴다 — 앱 롤의 직접 쓰기를 걷어낸 뒤(0164)
 *                                definer 만 쓸 수 있다. 둘 다 첫 줄이 assert_my_store 다.
 *   (settings_sync_operating_rule 은 0164 에서 지웠다 — settings 는 표시 폼이고 권위는 규칙이다.)
 *   stores_default_operating_rule 트리거 전용. 직접 못 부른다.
 *   stores_default_settings · stores_default_time_settings
 *                                트리거 전용(0165). definer 인 이유는 settings·
 *                                store_time_settings 가 앱 롤에 안 열려 있어서다 —
 *                                예전엔 시간대 트리거가 invoker 라 매장 생성이 42501 로 죽었다.
 *   create_store                 매장 생성의 공식 문(0165). auth.uid() 로 주인을 정하고
 *                                초기화 셋이 다 생겼는지 확인한다.
 *   close_due_business_days      매장을 안 가린다. 그래서 사람에게는 **아예 안 연다** —
 *                                크론(service_role)만 부른다(0137).
 *   close_business_day           첫 줄이 assert_my_store 다. definer 인 이유는 권한을
 *                                걷어낸 몸통(`close_business_day_row`)을 부르기 위해서다(0138).
 *                                0160 부터 앱 롤에는 안 열린 내부 몸통이다.
 *   save_sale                    같은 이유다(0145) — 몸통 `apply_sale_items` 를 부른다.
 *   amend_ended_business_day     같은 이유다(0145). 첫 줄이 assert_my_store.
 *   open_business_day            같은 이유다(0154) — 기한 지난 옛 날을 닫을 때 매장
 *                                검사 없는 몸통 `close_business_day_row` 를 부른다.
 *                                첫 줄이 assert_my_store 다.
 *   set_store_timezone           직접 쓰기를 걷어낸 store_time_settings 에 쓴다(0156).
 *                                첫 줄이 assert_my_store, 영업 중이면 45011 로 거부.
 *   transition_business_state    전이 한 문(0157) — 매장 검사 없는 몸통
 *                                set_break_row 를 부른다. 첫 줄이 assert_my_store.
 *   apply_due_breaks             매장을 안 가린다 — 크론(service_role)만 부른다(0157).
 *                                close_due_business_days 와 같은 자세.
 *   apply_operating_hours        무판본 저장 몸통(0163). 앱 롤엔 안 열린다 — 토큰 필수 문
 *                                set_operating_hours 만 여기로 온다.
 *   archive_my_store · retire_my_account
 *                                auth.uid() 소유 매장만 아카이브하고 원장을 보존하는 앱 문(0173).
 *   schedule_store_purge · purge_archived_store
 *                                보존 종료·승인·백업 근거가 필요한 service_role 전용 문(0173).
 *   report_client_rpc_error      auth.uid()별 5분 버킷에 최소 오류 지문만 기록하는 앱 문(0176).
 *                                ops 원본 표는 앱 롤에 닫혀 있고 서버가 예상 오류를 다시 거른다.
 *   ops_health_status            매장 원장을 읽지 않고 Cron·집계 신호만 내는 service_role 전용 문(0176).
 */
do $t$
declare v_now text; v_want text;
begin
  /*
   * ⚠ **시그니처까지** 본다. 이름만 비교하면 `set_operating_hours` 의 인자가 위험하게
   *   바뀌어도(예: 매장 인자가 빠져도) 이름이 같아 그대로 통과한다.
   *   definer 는 RLS 를 지나가므로 "무엇을 받는가"가 곧 권한 경계다.
   */
  select string_agg(p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
                    ' | ' order by p.proname, pg_get_function_identity_arguments(p.oid))
    into v_now
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.prokind = 'f' and p.prosecdef
     and pg_get_userbyid(p.proowner) = 'postgres';

  v_want := concat_ws(' | ',
    'amend_ended_business_day(p_store uuid, p_date date, p_base_revision integer, p_items jsonb, p_etc_items jsonb, p_extra_items jsonb, p_reason text)',
    'apply_due_breaks()',
    'apply_operating_hours(p_store uuid, p_weekly_hours jsonb, p_weekly_breaks jsonb, p_base_rule_id uuid, p_base_revision integer)',
    'archive_my_store(p_store uuid, p_reason text)',
    'close_business_day(p_store uuid)',
    'close_due_business_days()',
    'create_store(p_name text, p_timezone text)',
    'my_store_ids()',
    'open_business_day(p_store uuid, p_date date, p_close_time time without time zone)',
    'ops_health_status()',
    'purge_archived_store(p_store uuid, p_backup_reference text)',
    'purge_entity_changes()',
    'report_client_rpc_error(p_code text, p_detail text, p_client_platform text)',
    'retire_my_account()',
    'save_sale(p_store uuid, p_date date, p_items jsonb, p_etc_items jsonb, p_extra_items jsonb, p_base_revision integer, p_open_day boolean, p_open_close_time time without time zone)',
